import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('submit validation', async () => {
  const h = await createHost();
  assert.equal((await h.submit('a', 0)).ok, false);
  assert.equal((await h.submit('a', 4)).ok, false);
  assert.equal((await h.submit('a', 1.5)).ok, false);
  assert.equal((await h.submit('a', 2)).ok, true);
  assert.equal((await h.submit('a', 2)).ok, false);
  assert.deepEqual(await h.job('a'), { status: 'queued', tries: 0, maxTries: 2 });
  assert.equal(await h.job('zz'), null);
  for (const c of ['claim', 'succeed', 'fail', 'lost', 'cancel'] as const) {
    assert.equal((await h[c]('zz')).ok, false);
  }
});

test('retries until failed', async () => {
  const h = await createHost();
  await h.submit('a', 2);
  assert.equal((await h.succeed('a')).ok, false);
  assert.equal((await h.claim('a')).ok, true);
  assert.equal((await h.claim('a')).ok, false);
  assert.equal((await h.fail('a')).ok, true);
  assert.deepEqual(await h.job('a'), { status: 'queued', tries: 1, maxTries: 2 });
  await h.claim('a');
  assert.equal((await h.lost('a')).ok, true);
  assert.deepEqual(await h.job('a'), { status: 'failed', tries: 2, maxTries: 2 });
  assert.equal((await h.claim('a')).ok, false);
  assert.equal((await h.cancel('a')).ok, false);
});

test('cancellation', async () => {
  const h = await createHost();
  await h.submit('q', 1);
  assert.equal((await h.cancel('q')).ok, true);
  assert.equal((await h.job('q'))?.status, 'cancelled');
  await h.submit('r', 3);
  await h.claim('r');
  await h.cancel('r');
  assert.equal((await h.job('r'))?.status, 'cancelling');
  assert.equal((await h.cancel('r')).ok, false);
  assert.equal((await h.claim('r')).ok, false);
  await h.succeed('r');
  assert.deepEqual(await h.job('r'), { status: 'succeeded', tries: 1, maxTries: 3 });
  await h.submit('s', 3);
  await h.claim('s');
  await h.cancel('s');
  await h.fail('s');
  assert.deepEqual(await h.job('s'), { status: 'cancelled', tries: 1, maxTries: 3 });
  assert.equal((await h.succeed('s')).ok, false);
});

